import sys
from collections import defaultdict

def evaluate(node, flip_input):
    if node == flip_input:
        return 1 - values[node]
    if memo[node] != -1:
        return memo[node]
    if types[node] == 'IN':
        return values[node]
    if types[node] == 'AND':
        memo[node] = evaluate(children[node][0], flip_input) & evaluate(children[node][1], flip_input)
    elif types[node] == 'OR':
        memo[node] = evaluate(children[node][0], flip_input) | evaluate(children[node][1], flip_input)
    elif types[node] == "XOR":
        memo[node] = evaluate(children[node][0], flip_input) ^ evaluate(children[node][1], flip_input)
    elif types[node] == `NOT`:
        memo[node] = 1 - evaluate(children[node][0], flip_input)
    return memo[node]

n = int(sys.stdin.readline())
types = {}
values = {}
children = defaultdict(list)
memo = [-1] * (n + 1)

for i in range(1, n + 1):
    line = sys.stdin.readline().split()
    types[i] = line[0]
    if types[i] == 'IN':
        values[i] = int(line[1])
    else:
        for child in line[1:]:
            children[i].append(int(child))

inputs = [i for i in range(1, n + 1) if types[i] == 'IN']
results = []

for inp in inputs:
    memo = [-1] * (n + 1)
    results.append(evaluate(1, inp))

print(''.join(map(str, results)))
